import json,pathlib,hashlib
p=pathlib.Path('docs/review/fc77177/real_tool_closed_loop_sol_high_seven_artillery_window_mechanism_v1/session/candidates')
for d in sorted(p.glob('candidate-*')):
 j=json.loads((d/'simulation/diagnostic_summary.json').read_text());print(d.name,'KEYS',list(j))
 def scan(o,path=''):
  if isinstance(o,dict):
   for k,v in o.items():
    if any(z in k.lower() for z in ['active_enem','settle','spawn','end_time','duration','win','selected','unique_deployed','complete']):print(path+k,str(v)[:600])
    if isinstance(v,dict):scan(v,path+k+'.')
 scan(j)
f=pathlib.Path('output/normal_low_star_facts_v1/normal_low_star_facts.json'); print('CATALOG_HASH',hashlib.sha256(f.read_bytes()).hexdigest())
PY"

